import {buildMesh,faceGeometry,clamp} from './media-core.js';
import {drawMonster,mediaStickerSVG,drawMediaBackdrop} from './media-art.js';
export class FaceWarpRenderer{
 constructor(w=1280,h=720){this.canvas=document.createElement('canvas');this.canvas.width=w;this.canvas.height=h;this.gl=this.canvas.getContext('webgl',{alpha:false,preserveDrawingBuffer:true,antialias:false});if(!this.gl){this.canvas=document.createElement('canvas');this.canvas.width=w;this.canvas.height=h;this.ctx=this.canvas.getContext('2d');return;}const gl=this.gl,shader=(type,code)=>{const s=gl.createShader(type);gl.shaderSource(s,code);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;},program=this.program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,'attribute vec2 position;attribute vec2 texcoord;varying vec2 uv;void main(){uv=texcoord;gl_Position=vec4(position,0.,1.);}'));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,'precision mediump float;varying vec2 uv;uniform sampler2D image;void main(){gl_FragColor=texture2D(image,uv);}'));gl.linkProgram(program);gl.useProgram(program);this.pos=gl.createBuffer();this.uv=gl.createBuffer();this.indices=gl.createBuffer();this.texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,this.texture);for(const k of [gl.TEXTURE_WRAP_S,gl.TEXTURE_WRAP_T])gl.texParameteri(gl.TEXTURE_2D,k,gl.CLAMP_TO_EDGE);for(const k of [gl.TEXTURE_MIN_FILTER,gl.TEXTURE_MAG_FILTER])gl.texParameteri(gl.TEXTURE_2D,k,gl.LINEAR);}
 render(source,faces,edit,time=0){if(!faces.length||!edit.intensity||edit.filters.every(f=>f==='Original'))return source;const {width:w,height:h}=this.canvas,mesh=buildMesh(faces,edit.filters,edit.intensity,time,w,h,this.gl?48:22,this.gl?28:14);if(this.gl){const gl=this.gl;gl.viewport(0,0,w,h);gl.useProgram(this.program);for(const [name,buffer,data]of [['position',this.pos,mesh.vertices],['texcoord',this.uv,mesh.uv]]){gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);const loc=gl.getAttribLocation(this.program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);}gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,this.indices);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,mesh.indices,gl.STATIC_DRAW);gl.bindTexture(gl.TEXTURE_2D,this.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,source);gl.drawElements(gl.TRIANGLES,mesh.indices.length,gl.UNSIGNED_SHORT,0);}else{const ctx=this.ctx;ctx.clearRect(0,0,w,h);for(let i=0;i<mesh.indices.length;i+=3){const p=Array.from(mesh.indices.slice(i,i+3),n=>({x:(mesh.vertices[n*2]+1)*w/2,y:(1-mesh.vertices[n*2+1])*h/2,u:mesh.uv[n*2]*w,v:mesh.uv[n*2+1]*h}));const [a,b,c]=p,det=a.u*(b.v-c.v)+b.u*(c.v-a.v)+c.u*(a.v-b.v);if(Math.abs(det)<.001)continue;const solve=k=>[(a[k]*(b.v-c.v)+b[k]*(c.v-a.v)+c[k]*(a.v-b.v))/det,(a[k]*(c.u-b.u)+b[k]*(a.u-c.u)+c[k]*(b.u-a.u))/det,(a[k]*(b.u*c.v-c.u*b.v)+b[k]*(c.u*a.v-a.u*c.v)+c[k]*(a.u*b.v-b.u*a.v))/det],tx=solve('x'),ty=solve('y');ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.closePath();ctx.clip();ctx.setTransform(tx[0],ty[0],tx[1],ty[1],tx[2],ty[2]);ctx.drawImage(source,0,0,w,h);ctx.restore();}}return this.canvas;}
 dispose(){if(this.gl){for(const b of [this.pos,this.uv,this.indices])this.gl.deleteBuffer(b);this.gl.deleteTexture(this.texture);this.gl.deleteProgram(this.program);this.gl.getExtension('WEBGL_lose_context')?.loseContext();}}
}
const images=new Map();export function stickerImage(id){if(!images.has(id)){const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(mediaStickerSVG(id));images.set(id,image);}return images.get(id);}
export function layerPoint(layer,faces,w,h){let x=layer.x*w,y=layer.y*h,size=layer.size*w,rotation=layer.rotation||0;if(layer.anchor!=='screen'&&faces[layer.face||0]){const f=faces[layer.face||0],p=layer.anchor==='mouth'?f.mouth:layer.anchor==='eyes'?{x:(f.eyes[0].x+f.eyes[1].x)/2,y:(f.eyes[0].y+f.eyes[1].y)/2}:f.top;x=p.x+(layer.dx||0)*f.rx;y=p.y+(layer.dy||0)*f.ry;size=layer.size*f.rx*5;rotation+=f.angle;}return{x,y,size,rotation};}
export function drawLayers(ctx,edit,faces,time=0){const w=ctx.canvas.width,h=ctx.canvas.height;for(const layer of edit.layers){const p=layerPoint(layer,faces,w,h);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rotation);if(layer.kind==='monster'){drawMonster(ctx,layer.design,0,p.size*.1,p.size/280,{mouth:.15+Math.sin(time/300)*.1,smile:.6});}else if(layer.kind==='text'){ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 '+p.size*.25+'px Outfit,sans-serif';ctx.lineWidth=6;ctx.strokeStyle='#18243c';ctx.strokeText(layer.text,0,0);ctx.fillStyle=layer.color||'#fff4b6';ctx.fillText(layer.text,0,0);}else{const image=stickerImage(layer.id);if(image.complete&&image.naturalWidth)ctx.drawImage(image,-p.size/2,-p.size/2,p.size,p.size);}ctx.restore();}ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of edit.drawing){ctx.strokeStyle=stroke.color;ctx.lineWidth=stroke.size*w;ctx.beginPath();stroke.points.forEach((p,i)=>i?ctx.lineTo(p.x*w,p.y*h):ctx.moveTo(p.x*w,p.y*h));ctx.stroke();}}
function ellipse(ctx,x,y,rx,ry,fill,stroke){ctx.beginPath();ctx.ellipse(x,y,Math.max(.1,rx),Math.max(.1,ry),0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=3;ctx.stroke();}}
export function drawFaceEffect(ctx,face,effect,expression={},time=0){if(!face||effect==='None')return;const {rx,ry}=face;ctx.save();ctx.translate(face.center.x,face.center.y);ctx.rotate(face.angle);const mouthY=(face.mouth.y-face.center.y)*Math.cos(face.angle)-(face.mouth.x-face.center.x)*Math.sin(face.angle),open=expression.mouth||0;ctx.lineCap='round';
 if(effect==='Fire Breath'||effect==='Rainbow Mouth'){if(open>.15){for(let j=0;j<7;j++){ctx.strokeStyle=effect==='Fire Breath'?['#ff7354','#ffba51','#fff197'][j%3]:['#ff7ba4','#ffb36f','#ffe38c','#83e0b2','#7ac7f4','#b89aeb','#edabef'][j];ctx.lineWidth=rx*.12;ctx.beginPath();ctx.moveTo((j-3)*rx*.09,mouthY);ctx.quadraticCurveTo(Math.sin(time/150+j)*rx*.4,mouthY+ry*.7,(j-3)*rx*.24,mouthY+ry*(.7+open));ctx.stroke();}}}
 else if(effect==='Laser Eyes'){if((expression.blink||0)<.5){ctx.strokeStyle='#fc84a4';ctx.shadowBlur=18;ctx.shadowColor='#ff4986';ctx.lineWidth=8;for(const eye of face.eyes){const dx=eye.x-face.center.x,dy=eye.y-face.center.y,x=dx*Math.cos(face.angle)+dy*Math.sin(face.angle),y=-dx*Math.sin(face.angle)+dy*Math.cos(face.angle);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x*3,y-ry*1.4);ctx.stroke();}}}
 else if(effect==='Bubble Head'||effect==='Astronaut'){ellipse(ctx,0,-ry*.05,rx*1.3,ry*1.25,'#a5ecff16','#b4e8ee');ctx.strokeStyle='#f5ffff88';ctx.lineWidth=rx*.07;ctx.beginPath();ctx.ellipse(-rx*.62,-ry*.4,rx*.1,ry*.45,-.4,0,Math.PI*2);ctx.stroke();if(effect==='Astronaut'){ctx.fillStyle='#a8bad6';ctx.fillRect(-rx,ry*.8,rx*2,ry*.22);ellipse(ctx,-rx*1.2,0,rx*.2,ry*.3,'#b7cbe4','#516981');ellipse(ctx,rx*1.2,0,rx*.2,ry*.3,'#b7cbe4','#516981');}}
 else if(effect==='Robot Face'){ctx.fillStyle='#759ba770';ctx.strokeStyle='#b1e1de';ctx.lineWidth=4;ctx.beginPath();ctx.roundRect(-rx,-ry*.7,rx*2,ry*1.5,rx*.22);ctx.fill();ctx.stroke();for(const sign of [-1,1])ellipse(ctx,sign*rx*.42,-ry*.15,rx*.24,ry*.16,'#c7ffdb','#435f74');for(let i=0;i<5;i++){ctx.fillStyle='#323c61';ctx.fillRect(-rx*.4+i*rx*.17,mouthY,rx*.11,ry*(.1+open*.4));}ctx.strokeStyle='#f5cf9d';ctx.beginPath();ctx.moveTo(0,-ry*.7);ctx.lineTo(0,-ry*1.25);ctx.stroke();ellipse(ctx,0,-ry*1.25,rx*.1,rx*.1,'#ffca9a');}
 else{const cat=effect==='Cartoon Cat',dog=effect==='Cartoon Dog',alien=effect==='Alien Transformation',dragon=effect==='Dragon Transformation',monster=effect==='Monster',wizard=effect==='Wizard',pirate=effect==='Pirate',clown=effect==='Clown',hero=effect==='Superhero';
 for(const sign of [-1,1]){if(cat||dog||dragon||monster||effect==='Bouncing Animal Ears'){ctx.save();ctx.translate(sign*rx*.75,-ry*.8+Math.sin(time/160)*ry*.07);ctx.rotate(sign*.2);ctx.beginPath();ctx.moveTo(-rx*.3,ry*.2);ctx.quadraticCurveTo(-rx*.3,-ry*(dog?.2:.9),0,-ry*(dog?.05:.75));ctx.quadraticCurveTo(rx*.4,-ry*.3,rx*.3,ry*.2);ctx.closePath();ctx.fillStyle=dragon?'#92d8b1':monster?'#d5afe8':dog?'#c7a57e':'#efbbcc';ctx.fill();ctx.strokeStyle='#55546f';ctx.lineWidth=3;ctx.stroke();ctx.restore();}if(alien){ellipse(ctx,sign*rx*.5,-ry*.15,rx*.34,ry*.28,'#50446b','#b3f3d3');ellipse(ctx,sign*rx*.5-rx*.08,-ry*.23,rx*.1,ry*.09,'#c8fce9');}if(clown)for(let i=0;i<3;i++)ellipse(ctx,sign*rx,(-.5+i*.4)*ry,rx*.35,ry*.22,['#df9be3','#f0cb8a','#9eccee'][i]);}
 if(cat||dog){ellipse(ctx,0,mouthY-ry*.22,rx*.2,ry*.11,'#634962');if(cat){ctx.strokeStyle='#d5c7e2';ctx.lineWidth=4;for(const sign of [-1,1])for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(sign*rx*.17,mouthY);ctx.lineTo(sign*rx*.85,mouthY+(i-1)*ry*.18);ctx.stroke();}}}
 if(clown)ellipse(ctx,0,0,rx*.24,rx*.22,'#ed7f8e','#924969');if(hero){ctx.fillStyle='#ba8bdb99';ctx.beginPath();ctx.moveTo(-rx,-ry*.4);ctx.lineTo(0,-ry*.05);ctx.lineTo(rx,-ry*.4);ctx.lineTo(rx,ry*.1);ctx.lineTo(0,-ry*.23);ctx.lineTo(-rx,ry*.1);ctx.fill();}
 if(wizard||pirate){ctx.fillStyle=wizard?'#a58ae0':'#45486b';ctx.strokeStyle='#d9bfef';ctx.lineWidth=4;ctx.beginPath();if(wizard){ctx.moveTo(-rx*1.05,-ry*.65);ctx.lineTo(-rx*.18,-ry*2.15);ctx.lineTo(rx*.65,-ry*.7);}else{ctx.moveTo(-rx*1.3,-ry*.6);ctx.quadraticCurveTo(-rx,-ry*1.7,0,-ry*1.1);ctx.quadraticCurveTo(rx,-ry*1.7,rx*1.3,-ry*.6);}ctx.closePath();ctx.fill();ctx.stroke();ellipse(ctx,0,-ry*.9,rx*.14,rx*.14,'#f5df9f');if(pirate){ellipse(ctx,rx*.43,-ry*.18,rx*.26,ry*.2,'#393b55');ctx.strokeStyle='#5b5470';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-rx,-ry*.6);ctx.lineTo(rx*1.05,ry*.12);ctx.stroke();}}if(dragon||monster){ctx.fillStyle='#f5d6a5';for(const sign of [-1,1]){ctx.beginPath();ctx.moveTo(sign*rx*.5,-ry*.75);ctx.lineTo(sign*rx*.65,-ry*1.5);ctx.lineTo(sign*rx*.85,-ry*.65);ctx.fill();}}}
 ctx.restore();}
export function compositeFrame(output,source,trackerResult,edit,warp,{time=0,monster=null,expression={},selected=-1,mode='funny'}={}){
 const out=output.getContext('2d'),w=output.width,h=output.height,faces=(trackerResult?.faceLandmarks||[]).map(p=>faceGeometry(p,w,h)).filter(Boolean);if(!warp.composite){warp.composite=document.createElement('canvas');warp.composite.width=w;warp.composite.height=h;}const ctx=warp.composite.getContext('2d');ctx.clearRect(0,0,w,h);
 if(mode==='monster'){drawMediaBackdrop(ctx,monster?.background||'studio',time,w,h);drawMonster(ctx,monster,w/2,h*.61,Math.min(w/550,h/390),expression);}else if(source){ctx.drawImage(warp.render(source,faces,edit,time),0,0);for(let i=0;i<faces.length;i++)drawFaceEffect(ctx,faces[i],edit.effect,trackerResult?.expressions?.[i]||expression,time);if(monster&&edit.monsterLens)for(const f of faces)drawMonster(ctx,monster,f.center.x,f.center.y+f.ry*.9,f.rx/90,expression);}else{drawMediaBackdrop(ctx,'studio',time,w,h);ctx.fillStyle='#f4e9c9';ctx.textAlign='center';ctx.font='700 35px Outfit';ctx.fillText('Your imagination, live.',w/2,h/2);ctx.font='20px Outfit';ctx.fillText('Enable a camera or open a photo to begin.',w/2,h/2+45);}
 drawLayers(ctx,edit,faces,time);out.fillStyle='#101c30';out.fillRect(0,0,w,h);out.save();out.filter=`brightness(${edit.brightness}) contrast(${edit.contrast}) saturate(${edit.saturation})`;out.translate(w/2,h/2);out.rotate(edit.rotation*Math.PI/180);if(edit.flip)out.scale(-1,1);const crop=edit.crop,quarter=Math.abs(edit.rotation%180)===90,scale=quarter?Math.min(w/h,h/w):1;out.scale(scale,scale);out.drawImage(warp.composite,crop.x*w,crop.y*h,crop.w*w,crop.h*h,-w/2,-h/2,w,h);out.restore();if(edit.frame!=='None'){out.strokeStyle=edit.frame==='Comic'?'#ffcf86':edit.frame==='Neon'?'#bb96f4':'#b7eadb';out.lineWidth=edit.frame==='Comic'?30:17;out.strokeRect(15,15,w-30,h-30);if(edit.frame==='Stars')for(let i=0;i<18;i++){out.save();out.translate(i/17*w,24+(i%2)*(h-48));out.rotate(i);out.fillStyle='#f6df9b';out.fillRect(-8,-8,16,16);out.restore();}}return faces;
}
